div.g:evaluate:
var field={};

field.label = gs.nil(jelly.jvar_field.label) ? jelly.jvar_field.label : gs.getMessage("{0}", jelly.jvar_field.label);
field.hint = gs.nil(jelly.jvar_field.hint) ? jelly.jvar_field.hint : gs.getMessage("{0}", jelly.jvar_field.hint);
field.mandatory = false;
field;

var prefix = "";
prefix = jelly.jvar_cc_prefix;
var name = (gs.nil(prefix) ? jelly.jvar_field.name : (prefix + "-" + jelly.jvar_field.name));
name;
